use std::sync::{Arc, Mutex};
use std::thread;

// Shared counter `c` is a u8 whose declared range is 0..=2 and which starts at 0 (R2).
// It is protected by the mutex `m` (R4).

// Worker role: w1 and w2 both run this function.
fn worker(id: &'static str, m: Arc<Mutex<u8>>) {
    // Hold the mutual-exclusion lock for the whole read-modify-write (R4).
    let mut c = m.lock().unwrap();

    // Read the counter while holding the lock.
    // Increment only if the result stays within the required upper limit (R3).
    // The required upper limit is 1, so in every reachable state c never
    // exceeds 1, even though its declared range allows up to 2 (R5).
    if *c < 1 {
        *c += 1;
    }
    debug_assert!(*c <= 2, "counter out of declared range 0..=2");

    // Lock is released here when the guard `c` is dropped.
    let _ = id; // w1 / w2 label, kept for traceability
}

fn main() {
    // Supervising task: launches the two workers and waits for both (R1).
    let m = Arc::new(Mutex::new(0u8)); // c starts at 0 (R2)

    let m_w1 = Arc::clone(&m);
    let m_w2 = Arc::clone(&m);

    // Worker w1
    let h1 = thread::spawn(move || worker("w1", m_w1));
    // Worker w2
    let h2 = thread::spawn(move || worker("w2", m_w2));

    // Wait for both workers to finish. Each worker attempts its increment
    // exactly once and never loops or blocks indefinitely, so every
    // schedule and interleaving terminates (R6).
    h1.join().unwrap();
    h2.join().unwrap();

    // Exactly one of the two workers performed the increment, so the final
    // value is 1 (R5, R7).
    let c = m.lock().unwrap();
    println!("DONE done={}", *c);
}
```

Explanation of how the requirements are met:

- **R1**: `main` is the supervising task; it spawns `w1` and `w2` and joins both.
- **R2**: The shared counter `c` lives inside the mutex `m`, is a `u8` (declared range 0..=2, documented), and starts at `0`.
- **R3**: Each worker increments only under the condition `*c < 1`, i.e., only when the result stays within the required upper limit.
- **R4**: The lock guard `c` is acquired before reading and held through the write, so the two workers never touch the counter concurrently.
- **R5**: Since the guard condition caps the value at 1, no reachable state has `c > 1`, despite the declared range allowing 2.
- **R6**: Each worker performs a single bounded critical section with no loops or unbounded waits, so all interleavings terminate.
- **R7**: Exactly one worker succeeds in incrementing, so the program prints exactly `DONE done=1` and exits.
